TTS_WORKER:
Add-Type -AssemblyName System.Speech
$s = New-Object System.Speech.Synthesis.SpeechSynthesizer
$v = $env:KX_VOICE
if ($v) { try { $s.SelectVoice($v) } catch {} }
try { $s.Rate = [int]$env:KX_RATE } catch {}
while (($line = [Console]::In.ReadLine()) -ne $null) {
  if ($line -eq "__STOP__") { $s.SpeakAsyncCancelAll() }
  elseif ($line -eq "__LIST__") { [Console]::Out.WriteLine((($s.GetInstalledVoices() | % { $_.VoiceInfo.Name }) -join "|")) }
  elseif ($line.Length -gt 0) { $s.SpeakAsyncCancelAll(); [void]$s.SpeakAsync($line) }
}

WINSPEECH_WORKER:
$ErrorActionPreference = "Stop"
Add-Type -AssemblyName System.Speech
try {
  $r = New-Object System.Speech.Recognition.SpeechRecognitionEngine
  $r.SetInputToDefaultAudioDevice()
  $r.LoadGrammar((New-Object System.Speech.Recognition.DictationGrammar))
  $r.InitialSilenceTimeout = [TimeSpan]::FromSeconds(6)
  $r.EndSilenceTimeout = [TimeSpan]::FromSeconds(0.9)
  [Console]::Out.WriteLine('{"ready": true}')
} catch {
  [Console]::Out.WriteLine('{"error": "Windows speech recognition is not available: ' + ($_.Exception.Message -replace '"','') + '"}')
  exit 1
}
while (($line = [Console]::In.ReadLine()) -ne $null) {
  if ($line -eq "start") {
    [Console]::Out.WriteLine('{"listening": true}')
    try { $res = $r.Recognize() } catch { $res = $null }
    $t = ""
    if ($res -ne $null) { $t = $res.Text }
    [Console]::Out.WriteLine((@{text = $t} | ConvertTo-Json -Compress))
  } elseif ($line -eq "quit") { break }
}
